"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5025"],{791(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>h,frontMatter:()=>i,contentTitle:()=>a,toc:()=>c,assets:()=>l});var o=JSON.parse('{"id":"middle-school/class-7/biology/excretory-system","title":"The Human Excretory System","description":"Kidneys, structure of nephron, urine formation, and dialysis","source":"@site/docs/middle-school/class-7/biology/excretory-system.md","sourceDirName":"middle-school/class-7/biology","slug":"/middle-school/class-7/biology/excretory-system","permalink":"/bangalore-home-schooling/docs/middle-school/class-7/biology/excretory-system","draft":false,"unlisted":false,"editUrl":"https://github.com/karthik-r-bdump/bangalore-home-schooling/tree/main/docs/middle-school/class-7/biology/excretory-system.md","tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"title":"The Human Excretory System","sidebar_position":4,"description":"Kidneys, structure of nephron, urine formation, and dialysis"},"sidebar":"curriculumSidebar","previous":{"title":"Respiration in Plants & Animals","permalink":"/bangalore-home-schooling/docs/middle-school/class-7/biology/respiration"},"next":{"title":"History & Civics","permalink":"/bangalore-home-schooling/docs/middle-school/class-7/history-civics"}}'),s=t(4848),r=t(8453);let i={title:"The Human Excretory System",sidebar_position:4,description:"Kidneys, structure of nephron, urine formation, and dialysis"},a="\u{1F4A7} The Human Excretory System",l={},c=[{value:"\u{1F4DD} Solved Questions &amp; Study Guide",id:"-solved-questions--study-guide",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",pre:"pre",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"-the-human-excretory-system",children:"\u{1F4A7} The Human Excretory System"})}),"\n",(0,s.jsx)(n.p,{children:"Excretion is the removal of toxic metabolic waste products (principally urea, uric acid, and excess salts) from the human body."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"-solved-questions--study-guide",children:"\u{1F4DD} Solved Questions & Study Guide"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-markdown",children:"Theme-4: Human Body\nCHAPTER 5: Excretory System\nIntroduction\nThe excretory system in human beings consists of two bean shaped, dark red coloured organs\ncalled kidneys. In the humans, along with kidneys, liver, lungs and skin also functions as organs\nof excretion although their role is less as an excretory organ as compared to kidneys which are\nthe main organs of excretion.\n\nLearning New Words\n \u25CF\u200B Excretion: Removal of metabolic wastes, excess of salts and excess of water from the\n    body.\n \u25CF\u200B Accessory excretory organs: Kidneys are the chief excretory organs. Skin, lungs, liver\n    and large intestine act as accessory organs.\n \u25CF\u200B Nephron: The structural and functional unit of kidney.\n \u25CF\u200B Micturition: Passing out urine is called micturition.\n \u25CF\u200B Haematuria: Disease in which urine contains blood.\n \u25CF\u200B Dialysis: The removal of unwanted substances from the body through artificial kidney is\n    called dialysis.\n \u25CF\u200B Osmoregulation: To maintain the water contents constant in the body.\n\nEXCRETORY SYSTEM\nExcretion is a process of removal of metabolic waste (nitrogenous) materials from the body. It\ntakes place by means of excretory organs. Various life processes like nutrition, respiration, etc.\n\nproduce many unwanted and toxic substances like             , urea, uric acid in animals.\n\nThe organs that help the body to get rid of metabolic waste are called excretory organs, e.g.,\nkidneys in vertebrates.\n\nThe biological process involved in removal of the excess or toxic wastes from the body is called\nexcretion.\n\nIn humans, excretion involves the removal of urea and sweat. The urea is formed by the\ncombination of ammonia and carbon dioxide. There are several ways in which excess\nsubstances can be excreted from the body.\n \u25CF\u200B Carbon dioxide is breathed out by the lungs.\n \u25CF\u200B Sweat glands present in the skin help in the elimination of sweat from the body through its\n    pores. The sweat mainly consists of water, salts and urea.\n \u25CF\u200B Many waste substances are excreted in urine by the kidneys.\n \u25CF\u200B The liver helps in the breakdown of excess of proteins in the body.\n\fORGANS OF EXCRETION AND THEIR EXCRETORY PRODUCTS IN\nHUMANS\n\n Organs                                           Excretory products\n\n\n Kidneys                                          Water, urea, uric acid, excess of salts as\n                                                  urine (nitrogenous waste)\n\n Skin (Sweat glands)                              Excess of water, salts (like sodium chloride),\n                                                  lactic acid and urea in the form of sweat.\n\n Lungs                                            Carbon dioxide and water vapour in exhaled\n                                                  air (gaseous waste)\n\n Liver                                            Bile pigments (Bilirubin, Biliverdin), toxins,\n                                                  urea (produced in the liver and transported\n                                                  to the kidneys for excretion).\n\n\nLayout of the Human Excretory System\nDiagram Callouts & Key Features:\n\u25CF\u200B   Vena cava\n\u25CF\u200B   Aorta\n\u25CF\u200B   Diaphragm\n\u25CF\u200B   Left kidney\n\u25CF\u200B   Renal artery: Branch of the main artery (AORTA) which supplies oxygenated blood to the\n     kidney.\n\u25CF\u200B   Renal vein: It collects deoxygenated blood from the kidney and carries it to the main vein\n     (vena cava).\n\u25CF\u200B   Ureter: Urine passes through the ureter from each kidney to the bladder.\n\u25CF\u200B   Urinary bladder: Stores urine.\n\u25CF\u200B   Sphincter muscle: Keeps the bladder closed. It can relax to allow the bladder to empty.\n\u25CF\u200B   Urethra: Tube through which urine passes to the outside.\n      Fact File\n\n      The urinary system is very elaborate in human beings. The system consists of pair\n      of bean-shaped kidneys on either side of backbone. The kidneys convert urea into\n      urine. Urine leaves the kidneys through tubes called ureters which empty the urine\n      into a sac called the urinary bladder. It has a canal like opening called urethra\n      through which urine is eliminated from the body. The passage of urine to the\n      outside is called urination or micturition.\n\fSTRUCTURE OF A KIDNEY\n\nEach of our kidneys is about                 long and                   across. Our kidneys show\ntwo main regions:\n \u25CF\u200B Outer cortex: In the cortex region, urine is made.\n \u25CF\u200B Inner medulla: From the medulla, the urine flows into a cavity called renal pelvis and from\n    there into the ureter.\nInside each kidney there are about a million very small filtering units called nephrons or\nuriniferous tubules.\n\nThus, the excretory system of man consists of:\n 1.\u200B A pair of kidneys\n 2.\u200B A pair of ureters\n 3.\u200B A urinary bladder\n 4.\u200B Urethra\n\nExcretory System Components\nI. Kidney\n \u25CF\u200B Structure: The kidneys of man are reddish brown, bean shaped.\n \u25CF\u200B Location: They are present just below the stomach, one on either side of the vertebral\n    column.\n \u25CF\u200B Functions:\n     1.\u200B Elimination of toxic substances.\n     2.\u200B Regulation of water balance.\n     3.\u200B\n"})})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>a});var o=t(6540);let s={},r=o.createContext(s);function i(e){let n=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),o.createElement(r.Provider,{value:n},e.children)}}}]);